def update_institution_status(apps, schema_editor):
    institution = apps.get_model("web", "Institution")
    institution_section = apps.get_model("web", "InstitutionSection")
    for institution_name, new_order in CHANGED_DATA.items():
        new_section = institution_section.objects.get(name=ORDER[new_order])
        institution.objects.filter(name=institution_name).update(section=new_section)


def add_new_institutions(apps, schema_editor):
    institution = apps.get_model("web", "Institution")
    institution_section = apps.get_model("web", "InstitutionSection")
    for section_name, institution_names in NEW_DATA.items():
        section = institution_section.objects.get(name=section_name)
        for institution_name in institution_names:
            institution.objects.get_or_create(name=institution_name, section=section)


